// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";

import { mergeFacetValues } from "../../../main/frontend/graph-explorer/facet-values.ts";

test("endpoint facet refresh keeps local values missing from a truncated response", () => {
  const merged = mergeFacetValues(
    [
      { id: "first", label: "First", count: 2, visual: "local-first" },
      { id: "second", label: "Second", count: 1, visual: "local-second" },
    ],
    [{ id: "first", label: "First", count: 9 }],
  );

  assert.deepEqual(
    merged.map(({ id, count, visual }) => ({ id, count, visual })),
    [
      { id: "first", count: 9, visual: "local-first" },
      { id: "second", count: 1, visual: "local-second" },
    ],
  );
});
